function dump(n, depth) {
  const o = {name:n.name, type:n.type, x:Math.round(n.x), y:Math.round(n.y), w:Math.round(n.width), h:Math.round(n.height)};
  if (n.layoutMode && n.layoutMode!=="NONE") { o.lm=n.layoutMode; o.pad=[n.paddingLeft,n.paddingRight,n.paddingTop,n.paddingBottom]; o.gap=n.itemSpacing; o.ca=n.counterAxisAlignItems; o.pa=n.primaryAxisAlignItems; o.sizing=n.primaryAxisSizingMode+"/"+n.counterAxisSizingMode; }
  if (n.fills && n.fills.length) o.fills = n.fills.map(f=>f.type==="SOLID"?[Math.round(f.color.r*255),Math.round(f.color.g*255),Math.round(f.color.b*255),f.opacity]:f.type);
  if (n.strokes && n.strokes.length) o.strokes = n.strokes.map(f=>f.type==="SOLID"?[Math.round(f.color.r*255),Math.round(f.color.g*255),Math.round(f.color.b*255)]:f.type).concat([n.strokeWeight]);
  if (n.cornerRadius) o.r=n.cornerRadius;
  if (n.type==="TEXT") { o.chars=n.characters; o.font=n.fontName.style+" "+n.fontSize; o.lh=n.lineHeight; }
  if (n.children && depth>0) o.kids=n.children.map(c=>dump(c,depth-1));
  return o;
}
