async function makeTabBar(name,current,dark){
  const c=comp(name,375,83); c.fills=solid(dark?C.dark:C.white);
  if(!dark){c.strokes=solid(C.gray1);c.strokeWeight=1;c.strokeAlign="INSIDE";
    // top border only: use a line rect
    c.strokes=[]; const line=fr("TopLine",375,1);line.fills=solid(C.gray1);line.x=0;line.y=0;c.appendChild(line);}
  const items=[["Home","Icon_Home"],["Shop","Icon_Search"],["Favorites","Icon_Favorites"],["Bag","Icon_Bag"],["Profile","Icon_Profile"]];
  items.forEach((it,i)=>{
    const col=fr("Tab/"+it[0],75,60); col.x=i*75; col.y=8;
    col.layoutMode="VERTICAL"; col.counterAxisAlignItems="CENTER"; col.itemSpacing=4; col.primaryAxisSizingMode="AUTO"; col.counterAxisSizingMode="FIXED";
    const active=it[0]===current;
    const ic=inst(it[1]);
    if(active||dark===false&&false){}
    // recolor icon
    const colr=active?C.black:C.gray3;
    ic.findAll(n=>n.fills&&n.fills.length&&n.fills[0].type==="SOLID").forEach(n=>{try{n.fills=solid(colr)}catch(e){}});
    ic.name="Icon"; col.appendChild(ic);
    return col;
  });
  // labels
  for(let i=0;i<items.length;i++){
    const col=c.children[c.children.length-items.length+i];
  }
  // simpler: rebuild with labels
  c.children.slice(1).forEach(n=>n.remove());
  items.forEach((it,i)=>{
    const col=fr("Tab/"+it[0],75,60); col.x=i*75; col.y=8;
    col.layoutMode="VERTICAL"; col.counterAxisAlignItems="CENTER"; col.itemSpacing=4; col.primaryAxisSizingMode="AUTO"; col.counterAxisSizingMode="FIXED";
    const active=it[0]===current;
    const ic=inst(it[1]);
    const colr=active?C.black:C.gray3;
    ic.findAll(n=>{if(n.fills&&n.fills.length&&n.fills[0].type==="SOLID"){try{n.fills=solid(colr)}catch(e){}}});
    col.appendChild(ic);
    c.appendChild(col);
  });
  return c;
}
