function dump(n,ind){
  let s = ind + n.name + " | " + n.type + " | " + Math.round(n.width)+"x"+Math.round(n.height);
  if(n.type==="TEXT") s += " | chars=" + n.characters;
  const out=[s];
  if(n.children) for(const c of n.children) out.push(dump(c,ind+"  "));
  return out.join("\n");
}
