function fillCard(card, photoName, status, name, type, colors, price){
  const ph=card.findOne(n=>n.name==="Photo"); if(ph&&C[photoName]) ph.swapComponent(C[photoName]);
  const st=card.findOne(n=>n.name==="Status");
  if(st){ if(status){st.visible=true; st.characters=status;} else st.visible=false; }
  const nm=card.findOne(n=>n.name==="Name"); if(nm) nm.characters=name;
  const tp=card.findOne(n=>n.name==="Type"); if(tp){ if(type){tp.visible=true;tp.characters=type;} else tp.visible=false; }
  const cl=card.findOne(n=>n.name==="Colors"); if(cl){ if(colors){cl.visible=true;cl.characters=colors;} else cl.visible=false; }
  const pr=card.findOne(n=>n.name==="Price"); if(pr) pr.characters=price;
}

