const BLACK={r:0,g:0,b:0}, WHITE={r:1,g:1,b:1}, GRAY={r:0.45,g:0.45,b:0.45};

function txt(chars,size,style,color){const t=figma.createText();t.fontName={family:"Inter",style};t.fontSize=size;t.characters=chars;t.fills=[{type:"SOLID",color}];return t;}
function makeFrame(name,x,y,w,h,bg){const f=figma.createFrame();f.name=name;f.x=x;f.y=y;f.resize(w,h);f.fills=[{type:"SOLID",color:bg}];f.clipsContent=true;ws.appendChild(f);return f;}
function addShell(f,dark){const sb=C[dark?"Status Bar/White":"Status Bar"].createInstance();sb.x=0;sb.y=0;f.appendChild(sb);const hi=C[dark?"Home Indicator/White":"Home Indicator"].createInstance();hi.x=0;hi.y=f.height-34;f.appendChild(hi);}
function addTabBar(f,current){const tb=C["TabBar/"+current].createInstance();tb.x=0;tb.y=f.height-83;f.appendChild(tb);}

