const ws = figma.root.children.find(p=>p.id==="3:2");
const frames = ws.children.filter(n=>n.type==="FRAME"&&n.name.match(/^\d\d_/)).sort((a,b)=>a.name.localeCompare(b.name));
const out = frames.map(f=>f.name+" "+Math.round(f.width)+"x"+Math.round(f.height));
// fix straight apostrophes in text nodes inside frames (not components)
await figma.loadFontAsync({family:"Inter",style:"Regular"});
await figma.loadFontAsync({family:"Inter",style:"Medium"});
await figma.loadFontAsync({family:"Inter",style:"Semi Bold"});
let fixed=0;
for(const f of frames){
  for(const t of f.findAll(n=>n.type==="TEXT")){
    if(t.characters.includes("'")){
      try{ t.characters = t.characters.replace(/'/g,"\u2019"); fixed++; }catch(e){}
    }
  }
}
return out.join("\n")+"\napostrophes fixed: "+fixed;

const ws = figma.root.children.find(p=>p.id==="3:2");
const frames = ws.children.filter(n=>n.type==="FRAME"&&n.name.match(/^\d\d_/)).sort((a,b)=>a.name.localeCompare(b.name));
const out=[];
for(const f of frames.slice(0,6)){
  const texts=f.findAll(n=>n.type==="TEXT").map(t=>t.characters.replace(/\n/g," / "));
  const insts=f.findAll(n=>n.type==="INSTANCE").map(i=>i.name);
  out.push("=== "+f.name+" ===\nTEXTS: "+texts.join(" | ")+"\nINSTANCES: "+[...new Set(insts)].join(", "));
}
return out.join("\n\n");

