const out=[];
for(const p of figma.root.children){
  out.push(p.name+" ("+p.id+"): "+p.children.length+" children");
  for(const n of p.children.slice(0,40)) out.push("   "+n.name+" ["+n.type+"] x="+Math.round(n.x)+" y="+Math.round(n.y));
}
